using UnityEngine;

namespace Game.Scripts.Dungeon
{
    /// Materials, meshes and the light template the runtime ability effects are built from (generated by AbilityVfxBuilder).
    public sealed class AbilityVfxConfig : ScriptableObject
    {
        public static AbilityVfxConfig Instance => s_instance;

        /// Additive soft round glow: cores, motes, flashes.
        public Material Glow => _glow;
        /// Additive flame tongue.
        public Material Flame => _flame;
        /// Additive hot dot, meant for stretched billboards.
        public Material Spark => _spark;
        /// Additive irregular ember flake.
        public Material Ember => _ember;
        /// Additive thin ring, for horizontal billboards.
        public Material Ring => _ring;
        /// Additive rune circle.
        public Material Rune => _rune;
        /// Alpha-blended rune circle: dark glyphs.
        public Material RuneDark => _runeDark;
        /// Additive hunter's sigil.
        public Material Sigil => _sigil;
        /// Alpha-blended frost crystal / shard.
        public Material Crystal => _crystal;
        /// Alpha-blended smoke puff.
        public Material Smoke => _smoke;
        /// Alpha-blended droplet / bubble.
        public Material Drop => _drop;
        /// Alpha-blended ground puddle with a ragged edge.
        public Material Decal => _decal;
        /// Additive strip soft across its width: trails.
        public Material Beam => _beam;
        /// Opaque lit white, tinted per renderer with a property block.
        public Material Solid => _solid;
        /// Transparent lit glass.
        public Material Glass => _glass;
        /// Template of particle lights.
        public Light Light => _light;
        /// Bottle: submesh 0 glass, 1 liquid, 2 cork.
        public Mesh FlaskMesh => _flaskMesh;
        /// Weighted net in the XZ plane: submesh 0 rope, 1 iron weights.
        public Mesh NetMesh => _netMesh;
        /// War banner standing on its origin: submesh 0 wood, 1 cloth, 2 iron.
        public Mesh BannerMesh => _bannerMesh;

        private static AbilityVfxConfig s_instance;

        [SerializeField]
        private Material _glow;

        [SerializeField]
        private Material _flame;

        [SerializeField]
        private Material _spark;

        [SerializeField]
        private Material _ember;

        [SerializeField]
        private Material _ring;

        [SerializeField]
        private Material _rune;

        [SerializeField]
        private Material _runeDark;

        [SerializeField]
        private Material _sigil;

        [SerializeField]
        private Material _crystal;

        [SerializeField]
        private Material _smoke;

        [SerializeField]
        private Material _drop;

        [SerializeField]
        private Material _decal;

        [SerializeField]
        private Material _beam;

        [SerializeField]
        private Material _solid;

        [SerializeField]
        private Material _glass;

        [SerializeField]
        private Light _light;

        [SerializeField]
        private Mesh _flaskMesh;

        [SerializeField]
        private Mesh _netMesh;

        [SerializeField]
        private Mesh _bannerMesh;

        /// Makes this the config the static effect API builds from.
        public void Register()
        {
            s_instance = this;
        }
    }
}
